  const probe = document.createElement('span');
  probe.style.color = 'var(--e-global-color-accent)';
  document.body.appendChild(probe);
  out.accent_on_body = getComputedStyle(probe).color;
  probe.remove();

  // Resolved selection colors as RGB (re-derive to compute contrast)
  const p2 = document.createElement('div');
  p2.style.cssText = 'background-color: var(--e-global-color-accent); color: oklch(from var(--e-global-color-accent) round(calc(1 - l)) 0 h);';
  document.body.appendChild(p2);
  const cs = getComputedStyle(p2);
  out.bg = cs.backgroundColor;
  out.fg = cs.color;
  p2.remove();

  // contrast helper
  function parseRGB(s){ const m=s.match(/[\d.]+/g).map(Number); return m.slice(0,3); }
  function lin(c){ c/=255; return c<=0.03928? c/12.92 : Math.pow((c+0.055)/1.055,2.4); }
  function lum(rgb){ const [r,g,b]=rgb.map(lin); return 0.2126*r+0.7152*g+0.0722*b; }
  function contrast(a,b){ const L1=lum(parseRGB(a)),L2=lum(parseRGB(b)); const hi=Math.max(L1,L2),lo=Math.min(L1,L2); return (hi+0.05)/(lo+0.05); }
  out.contrast = +contrast(out.bg, out.fg).toFixed(2);

  // Also: search ALL stylesheets for where --e-global-color-accent is DEFINED
  const defs = [];
  for (const sheet of document.styleSheets) {
    let rules; try { rules = sheet.cssRules; } catch(e){ continue; }
    if (!rules) continue;
    for (const r of rules) {
      if (r.style && r.style.getPropertyValue('--e-global-color-accent')) {
        defs.push({ sel: r.selectorText, val: r.style.getPropertyValue('--e-global-color-accent').trim(), href: (sheet.href||'inline').split('/').pop() });
      }
    }
  }
  out.accent_definitions = defs;
  return out;
}

