  const accent = '#B12B79';
  function resolve(expr){
    const d = document.createElement('div');
    d.style.color = expr;
    document.body.appendChild(d);
    const c = getComputedStyle(d).color;
    d.remove();
    return c;
  }
  function parseRGB(s){ const m=(s.match(/[\d.]+/g)||[]).map(Number); return m.slice(0,3); }
  function lin(c){ c/=255; return c<=0.03928? c/12.92 : Math.pow((c+0.055)/1.055,2.4); }
  function lum(rgb){ const [r,g,b]=rgb.map(lin); return 0.2126*r+0.7152*g+0.0722*b; }
  function contrast(a,b){ const L1=lum(parseRGB(a)),L2=lum(parseRGB(b)); const hi=Math.max(L1,L2),lo=Math.min(L1,L2); return +((hi+0.05)/(lo+0.05)).toFixed(2); }

  const candidates = {
    "accent_itself":            accent,
    "A_round(1-l)":             `oklch(from ${accent} round(calc(1 - l)) 0 h)`,
    "A2_calc(1-round(l))":      `oklch(from ${accent} calc(1 - round(l)) 0 h)`,
    "B_round-nearest-explicit": `oklch(from ${accent} round(nearest, calc(1 - l), 1) 0 h)`,
    "C_step-via-clamp*999":     `oklch(from ${accent} clamp(0, calc((0.6 - l) * 999), 1) 0 h)`,
    "D_lightness-flip-1minusL": `oklch(from ${accent} calc(1 - l) 0 h)`,
  };
  const out = {};
  for (const [k,expr] of Object.entries(candidates)){
    const rgb = resolve(expr);
    out[k] = { resolved: rgb, contrast_vs_bg: contrast(accent, rgb) };
  }
  // What does l actually equal for the accent?
  out._L_of_accent = resolve(`oklch(from ${accent} l 0 0)`); // greyscale at accent's own L
  return out;
}

