() => {
  const accent = '#B12B79';
  // Force resolution to rgb by round-tripping through a canvas (engine resolves oklch->rgb on draw)
  function toRGB(expr){
    const d=document.createElement('div'); d.style.color=expr; document.body.appendChild(d);
    const c=getComputedStyle(d).color; d.remove();
    if (c.startsWith('rgb')) return c;
    // resolve oklch via canvas
    const cv=document.createElement('canvas'); cv.width=cv.height=1; const ctx=cv.getContext('2d');
    ctx.fillStyle=expr; ctx.fillRect(0,0,1,1);
    const [r,g,b]=ctx.getImageData(0,0,1,1).data;
    return `rgb(${r}, ${g}, ${b})`;
