input.function:
() => {
  function toRGB(expr){
    const cv=document.createElement('canvas'); cv.width=cv.height=1; const ctx=cv.getContext('2d');
    ctx.fillStyle='#000'; ctx.fillStyle=expr; ctx.fillRect(0,0,1,1);
    const [r,g,b]=ctx.getImageData(0,0,1,1).data; return [r,g,b];
  }
  function lin(c){ c/=255; return c<=0.03928? c/12.92 : Math.pow((c+0.055)/1.055,2.4); }
  function lum(rgb){ const [r,g,b]=rgb.map(lin); return 0.2126*r+0.7152*g+0.0722*b; }
  function contrast(a,b){ const L1=lum(a),L2=lum(b); const hi=Math.max(L1,L2),lo=Math.min(L1,L2); return (hi+0.05)/(lo+0.05); }
  const BLACK=[0,0,0], WHITE=[255,255,255];

  // For a given accent, what does each formula pick, and is it the OPTIMAL (max-contrast) pick?
  function evalFormula(accent, expr){
    const bg=toRGB(accent);
    const picked=toRGB(expr.replace(/ACCENT/g, accent));
    const cPick=contrast(bg,picked);
    const cBlack=contrast(bg,BLACK), cWhite=contrast(bg,WHITE);
    const best=Math.max(cBlack,cWhite);
    return { cPick:+cPick.toFixed(2), best:+best.toFixed(2), optimal: Math.abs(cPick-best)<0.05, passAA: cPick>=4.5 };
  }

  // Candidate formulas. Pivot is the OKLCH-L cutoff: if l < pivot -> use white (L=1), else black (L=0).
  // white-when-dark => text L = step(pivot, l)?  We want: l>=pivot -> black(0); l<pivot -> white(1).
  // color L = (l < pivot) ? 1 : 0  == 1 - round((l - pivot) + 0.5) clamped... simpler: 1 - clamp(0, (l-pivot)*BIG +0.5 ... )
  // Use: round(clamp(0, calc((l - PIVOT)*1000 + 0.5), 1))  -> 0 when l<pivot, 1 when l>=pivot  -> that's "black when light".
  // text L should be OPPOSITE: 1 - that.
  function formula(pivot){
    // L_text = 1 - step  where step=1 if l>=pivot else 0
    return `oklch(from ACCENT calc(1 - clamp(0, (l - ${pivot}) * 1000 + 0.5, 1)) 0 h)`;
  }

  // Sweep accents across hue at the troublesome mid lightness, plus real one + extremes
  const testAccents = ['#B12B79','#F0C400','#900042','#C02975','#660044','#4AA521','#808080','#00456C','#DEDDD1','#FFFFFF','#000000','#C86F47','#3A2E2A','#D1D591'];

  const pivots = [0.5, 0.62, 0.65, 0.7];
  const results = {};
  for (const pv of pivots){
    let fails=0, nonOptimal=0, worst=99, worstColor=null;
    for (const a of testAccents){
      const r=evalFormula(a, formula(pv));
      if(!r.passAA) { fails++; }
      if(!r.optimal) nonOptimal++;
      if(r.cPick<worst){ worst=r.cPick; worstColor=a; }
    }
    results['pivot_'+pv]={fails, nonOptimal, worstContrast:worst, worstColor};
  }
  // Detail for the winning-ish pivot 0.65 per accent
  const detail={};
  for (const a of testAccents){ detail[a]=evalFormula(a, formula(0.65)); }
  return { summary: results, detail_pivot065: detail };
}

