/*
 * base.css — Estilos globais e componentes base do tema
 * Extraído de: style.css
 * Tema: hello-elementor-child
 */

/* ==========================================================================
   2. ESTILOS GLOBAIS
   ========================================================================== */

/* --- 2.0 Proibir síntese de pesos/itálicos (fake-bold / fake-italic) ---
 * Just Sans só tem fonts reais para 400 e 800. Franie só para 400/700.
 * Sem essa regra, o browser sintetiza algoritmicamente pesos como 300, 500,
 * 600, 700 (Just Sans) ou 900 (Just Sans) — degrada legibilidade e quebra a
 * identidade tipográfica oficial (Manual de Marca §3.9). Com font-synthesis:none,
 * o browser cai no peso real mais próximo. Widgets Elementor que solicitam
 * pesos inexistentes precisam ser ajustados para valores reais (400/700/800).
 */
* {
    font-synthesis: none;
}

/* --- 2.1 HTML & Body --- */
html {
    font-size         : 16px;
    scrollbar-gutter  : stable;
    scroll-behavior   : smooth;
    scrollbar-color   : var(--e-global-color-bbe749d, #C02975) var(--e-global-color-e03d05f, #DEDDD1);
    scrollbar-width   : thin;
}

@media (prefers-reduced-motion: no-preference) {
    :has(:target) {
        scroll-behavior   : smooth;
        scroll-padding-top: 3rem;
    }
}

html body.elementor-default {
    background-color: var(--ucpa-color-offwhite);
    overflow-x      : hidden;
    position        : relative;
}

@media (max-width: 768px) {
    html, body {
        overflow-x: hidden;
    }
}

html body.elementor-kit-2553.elementor-page-26826 {
    background-color: var(--ucpa-color-offwhite);
}

/* --- 2.2 Tipografia --- */
h1, h2, h3, h4, h5, h6 {
    text-wrap: balance;
}

#content .tituloPagina {
    margin-top: 5rem;
}

figcaption {
    text-align: center;
    color     : var(--e-global-color-text);
}

/* --- 2.3 Links --- */
html body a[href*="mailto"]:hover {
    color: currentColor;
}

.elementor-kit-2553 a:hover {
    color: var(--e-global-color-text);
}

/* Widget Bureau SVG: preserva cor no hover para não afetar fill:currentColor */
.elementor-widget-bureau_svg a:hover {
    color: inherit !important;
}

/* --- 2.4 Seleção de Texto ---
 * Texto deve permanecer SELECIONÁVEL e legível em qualquer página.
 * Fundo = cor de destaque (Accent global). Texto = derivado do PRÓPRIO
 * destaque via OKLCH, sem hardcode nem fallback: arredonda a lightness do
 * accent para 0 ou 1 e usa o extremo oposto (preto p/ destaque claro,
 * branco p/ destaque escuro), com chroma 0 (neutro). Contraste garantido
 * automaticamente — se a paleta mudar no Elementor, a regra se re-resolve
 * sozinha. Suporte: OKLCH relative color + round() (Chrome 111+/125+,
 * Firefox 113+/118+, Safari 15.4+).
 */
::selection {
    background-color: var(--e-global-color-accent);
    color           : oklch(from var(--e-global-color-accent) round(calc(1 - l)) 0 h);
}

::-moz-selection {
    background-color: var(--e-global-color-accent);
    color           : oklch(from var(--e-global-color-accent) round(calc(1 - l)) 0 h);
}

/* --- 2.5 Outline --- */
* {
    outline-color: var(--e-global-color-accent);
}

/* --- 2.6 Scrollbar --- */
::-webkit-scrollbar {
    width : 8px;
    height: 8px;
}

::-webkit-scrollbar-track {
    background: var(--e-global-color-e03d05f, #DEDDD1);
}

::-webkit-scrollbar-thumb {
    background   : var(--e-global-color-bbe749d, #C02975);
    border-radius: 4px;
}

::-webkit-scrollbar-thumb:hover {
    background: color-mix(in lab, var(--e-global-color-bbe749d, #C02975) 75%, black 25%);
}


/* ==========================================================================
   3. COMPONENTES
   ========================================================================== */

/* --- 3.1 Labels --- */
html body.elementor-kit-2553 label {
    color: var(--ucpa-color-main, #000);
}

/* --- 3.2 Accordion JetTabs (Exposições Anteriores / Galeria) ---
 * O plugin JetTabs aplica `border-radius: 5px` em `.jet-toggle`
 * (jet-tabs-frontend.css). Como cada item só tem `border-bottom`,
 * o raio curva as pontas da linha divisória (efeito gancho).
 * Zeramos o raio para manter as divisórias 100% retas.
 */
.jet-accordion .jet-toggle,
.jet-toggle.jet-accordion__item {
    border-radius: 0;
}

