() => {
  const out = {};

  // 1) Confirm the NEW formula is served from base.css and old ones gone
  let served=null, fromBase=false, anyOld=false;
  for (const sheet of document.styleSheets) {
    let rules; try { rules = sheet.cssRules; } catch(e){ continue; }
    if (!rules) continue;
    for (const r of rules) {
      if (r.selectorText && /::selection/.test(r.selectorText)) {
        if (/e-global-color-accent/.test(r.cssText) && /clamp/.test(r.cssText)) {
          served = r.cssText; if ((sheet.href||'').includes('base.css')) fromBase=true;
        }
        if (/ucpa-color-white|color-mix|round\(/.test(r.cssText)) anyOld=true;
      }
    }
  }
  out.served_rule = served;
  out.from_base_css = fromBase;
  out.legacy_rule_present = anyOld;

  // 2) Resolve actual selection colors to RGB + WCAG contrast
  function toRGB(expr){
    const cv=document.createElement('canvas'); cv.width=cv.height=1; const ctx=cv.getContext('2d');
    ctx.fillStyle='#000'; ctx.fillStyle=expr; ctx.fillRect(0,0,1,1);
    const [r,g,b]=ctx.getImageData(0,0,1,1).data; return [r,g,b];
  }
  function lin(c){ c/=255; return c<=0.03928? c/12.92 : Math.pow((c+0.055)/1.055,2.4); }
  function lum(rgb){ const [r,g,b]=rgb.map(lin); return 0.2126*r+0.7152*g+0.0722*b; }
  function contrast(a,b){ const L1=lum(a),L2=lum(b); const hi=Math.max(L1,L2),lo=Math.min(L1,L2); return +((hi+0.05)/(lo+0.05)).toFixed(2); }

  const bg = toRGB('var(--e-global-color-accent)');
  const fg = toRGB('oklch(from var(--e-global-color-accent) calc(1 - clamp(0, (l - 0.62) * 1000 + 0.5, 1)) 0 h)');
  out.selection_bg_rgb = `rgb(${bg.join(',')})`;
  out.selection_fg_rgb = `rgb(${fg.join(',')})`;
  out.contrast = contrast(bg, fg);
  out.passes_AA = out.contrast >= 4.5;

  // 3) Verify body text is actually selectable (not user-select:none anywhere up the tree)
  const p = document.querySelector('p, .elementor-widget-text-editor, h2, h1');
  let node=p, blocked=false, blocker=null;
  while(node && node!==document.documentElement){
    const us = getComputedStyle(node).userSelect;
    if (us==='none'){ blocked=true; blocker=node.tagName+'.'+(node.className||''); break; }
    node=node.parentElement;
  }
  out.sample_text = p ? p.textContent.trim().slice(0,40) : null;
  out.text_selectable = !blocked;
  out.select_blocker = blocker;

  // 4) Actually perform a selection programmatically and confirm it sticks
  if (p) {
    const sel=window.getSelection(); sel.removeAllRanges();
    const r=document.createRange(); r.selectNodeContents(p); sel.addRange(r);
    out.selection_made = sel.toString().length > 0;
  }
  return out;
}

