() => {
  // Resolve a CSS expression that may contain var()/oklch() to concrete rgb,
  // by applying it to a DOM element and reading getComputedStyle (which for
  // backgroundColor/ color returns rgb()), with canvas only as fallback.
  function domRGB(expr){
    const d=document.createElement('div');
    d.style.backgroundColor=expr;
    document.body.appendChild(d);
    let v=getComputedStyle(d).backgroundColor;
    d.remove();
    if (v.startsWith('rgb')) return v.match(/\d+/g).slice(0,3).map(Number);
    // fallback: canvas (concrete colors only)
    const cv=document.createElement('canvas'); cv.width=cv.height=1; const ctx=cv.getContext('2d');
    ctx.fillStyle='#000'; ctx.fillStyle=v; ctx.fillRect(0,0,1,1);
    return Array.from(ctx.getImageData(0,0,1,1).data).slice(0,3);
  }
  function lin(c){ c/=255; return c<=0.03928? c/12.92 : Math.pow((c+0.055)/1.055,2.4); }
  function lum(rgb){ const [r,g,b]=rgb.map(lin); return 0.2126*r+0.7152*g+0.0722*b; }
